3. Interactive Lab Simulation
Use the sliders or number boxes below to change the tower height, object masses, or gravity, then click Play (or drag the timeline scrubber) to observe the fall in true 1:1 real-time (1 second on the simulation clock = 1 second on a real stopwatch).


function debounce(view, delay = 250) {
  return Generators.observe(notify =&gt; {
    let timer = null;
    const onInput = () =&gt; {
      clearTimeout(timer);
      timer = setTimeout(() =&gt; notify(view.value), delay);
    };
    view.addEventListener("input", onInput);
    notify(view.value);
    return () =&gt; view.removeEventListener("input", onInput);
  });
}

viewof tower_height_ui = Inputs.range([10, 250], {value: 56, step: 1, label: "Tower Height H (m)"})
viewof hammer_mass_ui = Inputs.range([0.2, 10.0], {value: 1.5, step: 0.1, label: "Hammer Mass (kg)"})
viewof feather_mass_ui = Inputs.range([0.001, 0.100], {value: 0.002, step: 0.001, label: "Feather Mass (kg)"})
viewof gravity_ui = Inputs.select(
  new Map([
    ["Earth (9.81 m/s²)", 9.81],
    ["Moon (1.62 m/s²)", 1.62],
    ["Mars (3.72 m/s²)", 3.72]
  ]),
  {value: 9.81, label: "Gravity g"}
)

tower_height = debounce(viewof tower_height_ui, 250)
hammer_mass = debounce(viewof hammer_mass_ui, 250)
feather_mass = debounce(viewof feather_mass_ui, 250)
gravity = gravity_ui
